def process_order(a_order: Order) -> Result[Receipt]:
    result = validate_order(a_order)
    if not result.is_success():
        return result
    result = calculate_totals(a_order)
    if not result.is_success():
        return result
    result = charge_payment(a_order)
    if not result.is_success():
        return result
    return Result.success(Receipt.from_order(a_order))
